// Handles both voice messages and text messages.
// For voice: downloads OGG from Telegram, transcribes via OpenAI Whisper.
// For text: passes through directly.
const msg = $input.first().json;
const message = msg.message || {};
const chatId = String(message.chat?.id || '');
const text = (message.text || '').trim();
const voice = message.voice || message.audio || null;

if (!chatId) return [];
if (text.startsWith('/')) return [];

const BOT_TOKEN = 'YOUR_BOT_TOKEN';
const OPENAI_KEY = 'YOUR_OPENAI_KEY';

let query = '';

if (voice) {
  // Step 1: Resolve file_id to a downloadable path
  const fileInfo = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.telegram.org/bot${BOT_TOKEN}/getFile`,
    qs: { file_id: voice.file_id },
    timeout: 10000
  });
  const filePath = fileInfo.result?.file_path;
  if (!filePath) throw new Error('Could not resolve voice file path from Telegram');

  // Step 2: Download the OGG audio binary
  const audioData = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.telegram.org/file/bot${BOT_TOKEN}/${filePath}`,
    encoding: null,
    timeout: 30000
  });
  const audioBuffer = Buffer.isBuffer(audioData) ? audioData : Buffer.from(audioData);

  // Step 3: Transcribe with OpenAI Whisper
  const transcription = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.openai.com/v1/audio/transcriptions',
    headers: { 'Authorization': `Bearer ${OPENAI_KEY}` },
    formData: {
      file: {
        value: audioBuffer,
        options: { filename: 'voice.ogg', contentType: 'audio/ogg; codecs=opus' }
      },
      model: 'whisper-1'
    },
    timeout: 60000
  });
  query = transcription.text || '';
} else if (text) {
  query = text;
} else {
  return [];
}

query = query.trim();
if (!query) return [];

return [{ json: { query, chatId } }];

// Detects whether the user wants a quick summary (normal) or full-page deep dive.
// Trigger words: 'go deeper', 'deeper:', 'elaborate', 'more detail', 'in depth', 'explain more'
const { query, chatId } = $input.first().json;
const q = (query || '').trim();

if (!q) return [];

const deepRegex = /^(go\s+)?deeper[:\s]|^elaborate[:\s]|^more\s+detail[:\s]|^in\s+depth[:\s]|^explain\s+more[:\s]/i;
let mode = 'normal';
let cleanQuery = q;

if (deepRegex.test(q)) {
  mode = 'deep';
  cleanQuery = q
    .replace(/^(go\s+)?deeper[:\s]*/i, '')
    .replace(/^elaborate[:\s]*/i, '')
    .replace(/^more\s+detail[:\s]*/i, '')
    .replace(/^in\s+depth[:\s]*/i, '')
    .replace(/^explain\s+more[:\s]*/i, '')
    .trim();
}

if (!cleanQuery) return [];
return [{ json: { query: cleanQuery, chatId, mode } }];

// Sends a typing indicator then hits SerpAPI Google Search.
// Returns up to 10 organic results (title, url, snippet).
const { query, chatId, mode } = $input.first().json;
const SERPAPI_KEY = 'YOUR_SERPAPI_KEY';
const BOT_TOKEN = 'YOUR_BOT_TOKEN';

// Let the user know the bot is working
await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.telegram.org/bot${BOT_TOKEN}/sendChatAction`,
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ chat_id: chatId, action: 'typing' }),
  timeout: 5000
}).catch(() => {});

const res = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://serpapi.com/search.json',
  qs: {
    engine: 'google',
    q: query,
    num: 10,
    api_key: SERPAPI_KEY
  },
  timeout: 15000
});

const results = (res.organic_results || []).slice(0, 10).map(r => ({
  title: r.title || '',
  url: r.link || '',
  snippet: r.snippet || ''
}));

if (results.length === 0) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.telegram.org/bot${BOT_TOKEN}/sendMessage`,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      chat_id: chatId,
      text: 'No search results found. Please try rephrasing your query.'
    }),
    timeout: 10000
  });
  return [];
}

return [{ json: { query, chatId, mode, results } }];

// Deep mode: scrapes full text from the top 3 result pages via Jina AI Reader.
// Jina AI (r.jina.ai) converts any URL to clean markdown — no API key needed.
const { query, chatId, results } = $input.first().json;
const topUrls = results.slice(0, 3).map(r => r.url);
const texts = [];

for (const url of topUrls) {
  try {
    const pageText = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://r.jina.ai/' + url,
      headers: {
        'Accept': 'text/plain',
        'X-Return-Format': 'text'
      },
      encoding: 'utf8',
      timeout: 20000
    });
    const text = typeof pageText === 'string' ? pageText : String(pageText);
    texts.push(text.slice(0, 3000));
  } catch(e) {
    texts.push('[Could not scrape: ' + url + ' — ' + e.message + ']');
  }
}

const content = topUrls.map((url, i) =>
  '=== Source ' + (i + 1) + ': ' + url + ' ===\n' + texts[i]
).join('\n\n---\n\n');

return [{ json: { query, chatId, mode: 'deep', content, urls: topUrls } }];

// Normal mode: formats the top 10 search snippets into a numbered list for Claude.
const { query, chatId, results } = $input.first().json;

const content = results.map((r, i) =>
  (i + 1) + '. ' + r.title + '\n   ' + r.snippet + '\n   ' + r.url
).join('\n\n');

return [{ json: {
  query,
  chatId,
  mode: 'normal',
  content,
  urls: results.slice(0, 3).map(r => r.url)
}}];

// Sends content to Claude, then sends the reply back to Telegram.
// Normal mode: 3-5 bullet point summary.
// Deep mode: detailed structured answer from full page content.
const { query, chatId, mode, content, urls } = $input.first().json;
const ANTHROPIC_KEY = 'YOUR_ANTHROPIC_KEY';
const BOT_TOKEN = 'YOUR_BOT_TOKEN';

const isDeep = mode === 'deep';

const systemPrompt = isDeep
  ? 'You are a thorough research assistant. The user requested an in-depth answer. Analyze the full page content provided and write a detailed, well-structured response with clear sections. Use Telegram HTML formatting only: <b>bold</b> for section headers, <a href=\'URL\'>Title</a> for source links. Be comprehensive and cite your sources.'
  : 'You are a concise research assistant. Summarize the search results in 3-5 bullet points. Start each bullet with \u2022 and a <b>bold key point</b> followed by a brief explanation (1-2 sentences). End with a Sources section listing up to 3 links formatted as <a href=\'URL\'>Site Name</a>. Use Telegram HTML only.';

const userPrompt = 'Research question: ' + query + '\n\n'
  + (isDeep ? 'Full page content from top results' : 'Search result snippets')
  + ':\n\n' + content;

let replyText = '';
try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.anthropic.com/v1/messages',
    headers: {
      'x-api-key': ANTHROPIC_KEY,
      'anthropic-version': '2023-06-01',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      model: 'claude-sonnet-4-6',
      max_tokens: isDeep ? 2048 : 1024,
      system: systemPrompt,
      messages: [{ role: 'user', content: userPrompt }]
    }),
    timeout: 45000
  });
  replyText = res.content?.[0]?.text || 'No response generated.';
} catch(e) {
  replyText = '<b>Error generating response:</b> ' + e.message;
}

await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.telegram.org/bot${BOT_TOKEN}/sendMessage`,
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({
    chat_id: chatId,
    text: replyText,
    parse_mode: 'HTML',
    disable_web_page_preview: true
  }),
  timeout: 15000
});

return [{ json: { status: 'done', query, mode, chatId } }];
